const $=s=>document.querySelector(s);$('#compare').addEventListener('input',e=>$('.compare').style.setProperty('--pos',e.target.value+'%'));document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d&& (e.offsetX<0||e.offsetY<0||e.offsetX>d.clientWidth||e.offsetY>d.clientHeight))d.close()}));$('#book').onclick=()=>$('#contact').showModal();$('#contactform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);$('#contactresult').textContent=`Thank you, ${f.get('name')}. Your consultation summary is ready for ${f.get('email')}. This is a local preview; no enquiry has been sent.`;const blob=new Blob([`THE BATHSTORE — Consultation enquiry\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nVision: ${f.get('vision')}`],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='bathstore-consultation.txt';a.textContent='Download your enquiry summary ↗';$('#contactresult').append(document.createElement('br'),a)};$('#approve').onclick=()=>{$('#approval').textContent='Concept estimate selected. A personalised scope and final quotation are required before approval.';$('#contact').showModal()};